def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Initialize an empty list to store the separated groups
    separated_groups = []

    # Step 3: Iterate through the input string and identify nested parentheses groups
    stack = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                separated_groups.append(paren_string[start:i+1])

    # Step 4: Check if each group is balanced
    def is_balanced(group):
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Step 5: Add balanced groups to the list
    balanced_groups = [group for group in separated_groups if is_balanced(group)]

    # Step 6: Return the list of separated groups
    return balanced_groups
